import os
import shutil
import csv


def task_func(target_value='332', csv_dir='./csv_files/', processed_dir='./processed_files/', simulate=False):
    """
    Scan csv_dir for CSV files, find the first row whose first cell equals target_value,
    and optionally move processed files to processed_dir.

    Returns:
        dict: {filename: row_index}
    """
    result = {}
    target = str(target_value)

    if not os.path.isdir(csv_dir):
        return result

    csv_files = sorted(
        filename for filename in os.listdir(csv_dir)
        if filename.lower().endswith('.csv') and os.path.isfile(os.path.join(csv_dir, filename))
    )

    if not simulate:
        os.makedirs(processed_dir, exist_ok=True)

    for filename in csv_files:
        file_path = os.path.join(csv_dir, filename)
        found_index = None

        try:
            with open(file_path, mode='r', newline='', encoding='utf-8-sig') as f:
                reader = csv.reader(f)
                for idx, row in enumerate(reader):
                    if row and row[0] == target:
                        found_index = idx
                        result[filename] = idx
                        break
        except (OSError, UnicodeError):
            # If a file cannot be read, skip it gracefully.
            found_index = None

        if not simulate:
            dest_path = os.path.join(processed_dir, filename)
            try:
                if os.path.exists(dest_path):
                    os.remove(dest_path)
                shutil.move(file_path, dest_path)
            except OSError:
                # Skip move errors gracefully.
                pass

    return result
